using UnityEngine;

namespace OpenSkies.Gameplay
{
    /// <summary>
    /// Process-wide settings applied before the first scene loads. Scene content
    /// is not created here: scenes are generated by Editor commands
    /// (see FlightPrototypeSceneBuilder).
    /// </summary>
    public static class AppBootstrap
    {
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        static void Configure()
        {
            var config = GameConfig.Load();
            QualitySettings.vSyncCount = 0; // otherwise targetFrameRate is ignored on desktop/WebGL
            Application.targetFrameRate = config.targetFrameRate;
            Screen.sleepTimeout = SleepTimeout.NeverSleep; // the screen must not dim mid-flight
            // Cap catch-up physics after a slow frame (default 0.333 s = up to ~16 steps at
            // 50 Hz), so a hitch on a slow phone cannot snowball into further slow frames.
            Time.maximumDeltaTime = config.maxPhysicsCatchUpSeconds;
        }
    }
}
